create or replace function private.admin_mfa_ok() returns boolean language sql stable security definer set search_path = '' as $$ select (select auth.uid()) is not null and coalesce((select auth.jwt()->>'aal'),'aal1')='aal2' and exists(select 1 from auth.mfa_factors where user_id=(select auth.uid()) and status='verified') $$; revoke all on function private.admin_mfa_ok() from public,anon,service_role; grant execute on function private.admin_mfa_ok() to authenticated;
